#ifndef G_SAVETRANSCODE_H
#define G_SAVETRANSCODE_H
// ILP32<->64-bit savegame transcoder (g_savetranscode.cpp, generated by
// tools/savelayout/gen_savetranscode.py). On 64-bit builds the raw struct-dump chunks
// GENT/GCLI/GNPC/LVLC are (de)serialized in the canonical 32-bit on-disk layout, so saves stay
// byte-identical to the armv7/PC-retail format.
//
// One switch for every 64-bit ABI: LP64 (macOS/Linux arm64+x86_64; long and pointers 8 bytes)
// and LLP64 (Win64; long 4, pointers 8). The saved structs hold no long, so both ABIs have the
// same native layout and share one table (tools/savelayout/README.md).
#if defined(__LP64__) || defined(_WIN64)
#define EF_SAVE_TRANSCODE 1
#elif defined(__x86_64__) || defined(__aarch64__) || defined(_M_X64) || defined(_M_ARM64)
#error "64-bit target without __LP64__/_WIN64: savegames would be written in the native layout"
#endif

#ifdef EF_SAVE_TRANSCODE
// Returns NULL for width-stable chids (raw passthrough).
const void* SG_TranscodeDesc(unsigned long chid);
int  SG_TranscodePack(const void* desc, const unsigned char* native, unsigned char* disk);
void SG_TranscodeUnpack(const void* desc, const unsigned char* disk, unsigned char* native);
int  SG_TranscodeDiskSize(const void* desc);
int  SG_TranscodeNativeSize(const void* desc);
#endif

#endif // G_SAVETRANSCODE_H
